function defaultCursorModelsRunner(): Promise<CursorModelsCommandResult> {
  return new Promise(resolve => {
    execFile("cursor-agent", ["models"], {
      encoding: "utf8",
      timeout: CURSOR_MODELS_TIMEOUT_MS,
      maxBuffer: MAX_BUFFER_BYTES,
      killSignal: "SIGKILL",
    }, (error, stdout, stderr) => {
      resolve({
        status: error ? (typeof error.code === "number" ? error.code : null) : 0,
        stdout: typeof stdout === "string" ? stdout : "",
        stderr: typeof stderr === "string" ? stderr : "",
        hasError: Boolean(error),
      });
    });
  });
}

type CursorModelsRunner = () => CursorModelsCommandResult | Promise<CursorModelsCommandResult>;
let cursorModelsRunner: CursorModelsRunner = defaultCursorModelsRunner;

async function fetchCursorModelsFromCli(): Promise<AdapterModel[]> {
  const result = await cursorModelsRunner();
  const { stdout, stderr } = result;
  if (result.hasError && stdout.trim().length === 0 && stderr.trim().length === 0) return [];
  if ((result.status ?? 1) !== 0 && !/available models?:/i.test(`${stdout}\n${stderr}`)) return [];
  return parseCursorModelsOutput(stdout, stderr);
}

export async function listCursorModels(): Promise<AdapterModel[]> {
  if (cached && cached.expiresAt > Date.now()) return cached.models;
  if (pending) return pending;
  pending = (async () => {
    const discovered = await fetchCursorModelsFromCli().catch(() => []);
    // Real account-specific IDs are authoritative, including effort/fast suffixes.
    const models = discovered.length > 0
      ? dedupeModels(discovered)
      : dedupeModels(cursorFallbackModels.filter(model => model.id === "auto"));
    cached = {
      expiresAt: Date.now() + (discovered.length > 0 ? CURSOR_MODELS_CACHE_TTL_MS : CURSOR_MODELS_FAILURE_CACHE_TTL_MS),
      models,
    };
    return models;
  })();
  try { return await pending; }
  finally { pending = null; }
}

  cached = null;
  pending = null;
}

// "auto" delegates to the existing CLI configuration; it is not a vendor model ID.
